<?php /** The waste logs at this site by day (screen `waste-list`). Data: rows, total, page, filters, week, reasons, seesCost, mayLog, mayReview, highlight, notice */ $pdo = db(); $tz = site_timezone(); ?>
<?= view('shared/header.php', ['id' => 'waste-list', 'title' => 'Waste', 'crumbs' => [['Home', '/'], ['Stock', '/stock/'], ['Waste', null]], 'action' => $mayLog ? hx_link('/waste/new', '<i class="feather-plus me-1"></i>Log waste', 'btn btn-danger btn-touch', 'id="waste-list-new-btn"') : '']) ?>
<div class="main-content" id="waste-list-content">
    <?= view('stock/_assets.php') ?>
    <?= view('shared/notice.php', ['notice' => $notice]) ?>
    <?= view('waste/_week.php', ['week' => $week]) ?>
    <form method="get" action="/waste/" hx-get="/waste/" hx-target="#page-content" hx-push-url="true" hx-trigger="submit, change from:select" class="card mb-3" id="waste-list-filters"><div class="card-body row g-2 align-items-end">
        <div class="col-6 col-md-2"><label class="form-label fs-12 text-muted" for="waste-filter-from">From</label><input type="date" name="from" id="waste-filter-from" class="form-control btn-touch" value="<?= e($filters['from']) ?>"></div>
        <div class="col-6 col-md-2"><label class="form-label fs-12 text-muted" for="waste-filter-to">To</label><input type="date" name="to" id="waste-filter-to" class="form-control btn-touch" value="<?= e($filters['to']) ?>"></div>
        <div class="col-6 col-md-2"><label class="form-label fs-12 text-muted" for="waste-filter-stage">Stage</label><select name="stage" id="waste-filter-stage" class="form-select btn-touch"><option value="">Any</option><?php foreach (WASTE_STAGES as $k => $w): ?><option value="<?= $k ?>" <?= $filters['stage'] === $k ? 'selected' : '' ?>><?= e($w) ?></option><?php endforeach; ?></select></div>
        <div class="col-6 col-md-3"><label class="form-label fs-12 text-muted" for="waste-filter-reason">Reason</label><select name="reason" id="waste-filter-reason" class="form-select btn-touch"><option value="">Any</option><?php foreach ($reasons as $r): ?><option value="<?= e($r['code']) ?>" <?= $filters['reason'] === $r['code'] ? 'selected' : '' ?>><?= e($r['name']) ?></option><?php endforeach; ?></select></div>
        <div class="col-12 col-md-3"><button type="submit" class="btn btn-light btn-touch w-100" id="waste-filter-apply">Filter</button></div></div></form>
    <?php if ($rows === []): ?><div class="card" id="waste-list-empty"><div class="card-body text-center text-muted py-5">No waste logged in the window.</div></div><?php else: ?>
    <div class="card"><div class="stock-table-wrap"><table class="table align-middle mb-0 fs-12" id="waste-table"><thead><tr><th>When</th><th>Stage</th><th>Reason</th><th>What</th><th class="text-end">Quantity</th><th class="text-end">Cost</th><th>Station</th><th>Day part</th><th>Disposition</th><th>Who</th><th>Status</th><th></th></tr></thead><tbody>
    <?php foreach ($rows as $w): $wid = $w['waste_log_id']; ?><tr id="waste-row-<?= $wid ?>" class="<?= $highlight === $wid ? 'table-warning' : '' ?>">
        <td class="text-nowrap"><?= e($w['business_date']) ?><div class="fs-11 text-muted"><?= e(format_ts($w['logged_at'], $tz, 'g:i A')) ?></div></td><td><?= chip(WASTE_STAGES[$w['stage']], ['ingredient' => 'secondary', 'prep' => 'warning', 'plate' => 'danger'][$w['stage']]) ?></td><td><?= e($w['reason']) ?></td>
        <td><?= $w['ingredient_id'] ? hx_link('/ingredients/' . $w['ingredient_id'], e($w['ingredient'])) : hx_link('/recipes/' . $w['recipe_id'], e($w['recipe'])) ?></td>
        <td class="text-end"><?= $w['ingredient_id'] && $w['qty_base'] !== null ? e(format_qty($pdo, $w['ingredient_id'], $w['qty_base'], $w['gross_weight_g'] !== null ? 'g' : ($w['unit_code'] === 'g' ? 'g' : $w['unit_code']))) : e(fmt_num($w['qty'], 4) . ' ' . $w['unit_code']) ?></td>
        <td class="text-end"><?= $seesCost ? money($w['cost'] === null ? null : (string) $w['cost']) : money(null) ?></td><td><?= e((string) $w['station']) ?></td><td><?= e((string) $w['day_part']) ?></td><td><?= e(WASTE_DISPOSITIONS[$w['disposition']] ?? $w['disposition']) ?></td><td><?= e((string) $w['logged_by_name']) ?></td><td><?= doc_chip($w['status']) ?></td>
        <td><div class="d-flex flex-wrap gap-1"><?= hx_link('/waste/' . $wid, 'Open', 'btn btn-light btn-sm btn-touch') ?><?php if ($mayReview && $w['status'] === 'posted'): ?> <form method="post" action="/waste/review.php" hx-post="/waste/review.php" hx-target="#flash" class="d-inline"><?= csrf_field() ?><input type="hidden" name="waste" value="<?= $wid ?>"><button type="submit" class="btn btn-light btn-sm btn-touch" id="waste-review-<?= $wid ?>">Review</button></form><?php endif; ?></div></td></tr><?php endforeach; ?>
    </tbody></table></div></div><?php endif; ?>
</div>
